// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Prisma CLI (migrate, db, studio...) usa EXCLUSIVAMENTE MIGRATION_DATABASE_URL
// (rol senas_migrator). A propósito NO hay fallback a DATABASE_URL: esa variable
// es la de NestJS en ejecución (rol senas_app) y no debe usarse para migrar.
// Si falta, los comandos que necesitan base de datos (p. ej. `migrate deploy`)
// fallan; `validate` y `generate` no se conectan y siguen funcionando.
export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["MIGRATION_DATABASE_URL"],
  },
});
